      VtaCalendarBusyTarget(
        holder: json['holder'] as String,
        pageId: json['pageId'] as String,
      );

  final VtaCalendarDid holder;

  /// The booking page's identifier at its holder.
  final String pageId;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'holder': holder,
        'pageId': pageId,
      };
}

/// The principal's choice to share busy times with one booking page, for one context.
class VtaCalendarBusyShare {
  const VtaCalendarBusyShare({
    required this.contextId,
    required this.target,
    required this.enabled,
    this.lastSharedAt,
  });

  /// Read this payload from a decoded JSON object.
  factory VtaCalendarBusyShare.fromJson(Map<String, dynamic> json) =>
      VtaCalendarBusyShare(
        contextId: json['contextId'] as String,
        target: VtaCalendarBusyTarget.fromJson(
            json['target'] as Map<String, dynamic>),
        enabled: json['enabled'] as bool,
        lastSharedAt: json['lastSharedAt'] as String?,
      );

  final VtaCalendarContextId contextId;
  final VtaCalendarBusyTarget target;

  /// Whether busy times are shared.
  final bool enabled;

  /// When the VTA last sent busy times to the target.
  final VtaCalendarInstant? lastSharedAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'contextId': contextId,
        'target': target.toJson(),
        'enabled': enabled,
        if (lastSharedAt != null) 'lastSharedAt': lastSharedAt!,
      };
}
